<?php require_once __DIR__ . '/../includes/layout.php'; require_role(['super_admin']); verify_csrf();
if($_SERVER['REQUEST_METHOD']==='POST'){ $name=trim($_POST['name']??''); if($name){$stmt=db()->prepare('INSERT INTO project_categories (name, enabled) VALUES (?,1) ON DUPLICATE KEY UPDATE enabled=1'); $stmt->bind_param('s',$name); $stmt->execute(); audit('create','project_category',null,$name);} redirect('settings/categories.php'); }
if(isset($_GET['toggle'])){ $id=(int)$_GET['toggle']; db()->query('UPDATE project_categories SET enabled = 1 - enabled WHERE id='.$id); audit('toggle','project_category',$id); redirect('settings/categories.php'); }
$rows=db()->query('SELECT * FROM project_categories ORDER BY name'); page_header('Project Categories'); ?><div class="panel"><h2>Add Category</h2><form class="form-grid" method="post"><?= csrf_field() ?><label>Category name<input name="name" required></label><button class="btn btn-primary">Save</button></form></div><div class="panel"><h2>Categories</h2><table><thead><tr><th>Name</th><th>Status</th><th></th></tr></thead><tbody><?php while($r=$rows->fetch_assoc()): ?><tr><td><?= e($r['name']) ?></td><td><?= $r['enabled']?'Enabled':'Disabled' ?></td><td><a class="btn btn-sm" href="?toggle=<?= $r['id'] ?>">Toggle</a></td></tr><?php endwhile; ?></tbody></table></div><?php page_footer(); ?>
